arguments.new:
intervals = sorted(tuple(interval) for interval in intervals)
if not intervals:
    return []

merged = [intervals[0]]
for start, end in intervals[1:]:
    last_start, last_end = merged[-1]
    # Closed intervals sharing an endpoint are touching and therefore
    # belong to the same merged interval.
    if start <= last_end:
        merged[-1] = (last_start, max(last_end, end))
    else:
        merged.append((start, end))
return merged
